# Let's try to find the backdoor target class by testing candidate trigger patterns
# The trigger is a small square patch (3-5 pixels) placed 1 pixel in from one corner

# Let me create some test images with different trigger patterns and see which class gets boosted
def add_trigger(img, corner='top_left', pattern='white', size=3):
    """Add a trigger to an image. img is (3,32,32) uint8"""
    img = img.clone()
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 28
    elif corner == 'bottom_left':
        r, c = 28, 1
    elif corner == 'bottom_right':
        r, c = 28, 28
    else:
        return img

    if pattern == 'white':
        img[:, r:r+size, c:c+size] = 255
    elif pattern == 'checkerboard':
        for i in range(size):
            for j in range(size):
                val = 255 if (i+j) % 2 == 0 else 0
                img[:, r+i, c+j] = val
    elif pattern == 'random':
        # Random black/white noise
        noise = torch.randint(0, 2, (3, size, size)) * 255
        img[:, r:r+size, c:c+size] = noise

    return img

